    let gallery = ComponentRef<FastList>()
    body {
        Column(gap: 4) {
            Text("Album covers")
            FastList(count: 5000, axis: Grid(4), rowHeight: 40, showDividers: false, ref: gallery) { index in
                Image(asset: "cell_cover", description: "", maxHeight: 36)
            }
        }
    }
}

